(() => {
  'use strict';
  const seed=JSON.parse(document.getElementById('seed').textContent), catalog=JSON.parse(document.getElementById('catalog').textContent);
  const staff=document.body.dataset.role==='ministry', actor=staff?'Ministry':'Applicant';
  const KEY='sk-childcare-forms-v2', $=s=>document.querySelector(s), clone=x=>JSON.parse(JSON.stringify(x));
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const names={family_home:'Family child care home',group_home:'Group family child care home',centre:'Child care centre'};
  const phaseNames={intake:'Application package',preopening:'Prepare to open',review:'Visits & Ministry review',optional:'Optional forms'};
  const statusNames={draft:'In progress',submitted:'Ready for review',changes_requested:'Update requested',accepted:'Reviewed'};
  let saved=null,storageError='',m,rawSaved=null;
  try{rawSaved=localStorage.getItem(KEY)||localStorage.getItem('sk-childcare-applications-v1');saved=JSON.parse(rawSaved||'null');}catch{try{localStorage.setItem(KEY+'-recovery',rawSaved||'');}catch{}storageError='Saved work could not be read. Download the retained recovery copy from the information menu.';}
  try{m=new FormWorkspace(seed,catalog,saved);}catch{m=new FormWorkspace(seed,catalog);try{localStorage.setItem(KEY+'-recovery',JSON.stringify(saved));}catch{}storageError='The previous saved record could not be loaded. A recovery copy was retained; download it from the information menu.';}
  let selected=(staff?m.state.cases:m.ownCases())[0]?.id, view='case',tab='overview',formId=null,sectionIndex=0,formDraft={},draftBaseline={},pendingState=null,dirty=false,query='',filter='',modalHandler=null,lastFocus=null,aiTarget=null;
  const c=()=>m.state.cases.find(x=>x.id===selected), schema=()=>m.schema(formId);
  const b=(text,action,attrs='',kind='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${attrs}>${text}</button>`;
  const inf=(topic,label='More information')=>`<button type="button" class="icon-btn info-inline" aria-label="${esc(label)}" title="${esc(label)}" data-action="info" data-topic="${esc(topic)}">i</button>`;
  const badge=(text,kind='neutral')=>`<span class="badge ${kind}">${esc(text)}</span>`;
  const date=d=>d?new Intl.DateTimeFormat('en-CA',{day:'numeric',month:'short',year:'numeric',timeZone:'America/Regina'}).format(new Date(d.length===10?d+'T12:00:00Z':d)):'—';
  const blank=v=>v===undefined||v===null||v===''||(Array.isArray(v)&&!v.length);
  function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').hidden=true,4500);}
  function persist(message='Saved on this device',draw=true){try{localStorage.setItem(KEY,JSON.stringify(m.state));storageError='';}catch{storageError='This browser could not save your changes. Export the case before closing.';}if(draw)render();toast(storageError||message);}
  function ownList(){return staff?m.state.cases:m.ownCases();}
  function record(f){return m.record(c(),f.id||f);}
  function report(f,role='Applicant'){return m.report(c(),f.id||f,role);}
  function fields(f){return f.sections.flatMap(s=>s.fields.map(field=>({field,owner:s.owner,section:s})));}
  function unaddressed(f){return fields(f).filter(x=>{const field=x.field,v=m.fieldValue(c(),f.id,field,x.owner);if(x.owner!=='Applicant'||field.type==='calculated'||field.required||!m.fieldVisible(c(),f.id,field)||field.signatureDraft||/signature|previous|if applicable|if different|supplier.*no|comments/i.test(field.label))return false;if(field.type==='table')return !v?.length||v.some(row=>field.columns.some(col=>!col.readonly&&!col.readOnly&&col.type!=='calculated'&&blank(row[col.id])));return blank(v);});}
  function status(f){const r=record(f),p=report(f);if(f.kind==='unavailable')return {text:'Ministry template needed',kind:'neutral'};if(r.status==='changes_requested')return{text:'Update requested',kind:'warning'};if(r.status==='accepted')return{text:'Reviewed',kind:'success'};if(r.status==='submitted')return{text:'Ready for review',kind:'warning'};if(p.complete&&Object.keys(r.values).length&&!unaddressed(f).length)return{text:'Draft prepared',kind:'success'};return{text:p.answered||Object.keys(r.values).length?'In progress':f.kind==='external'?'Outside evidence':'Not started',kind:'neutral'};}
  function summary(){const fs=m.applicable(c()).filter(f=>f.required);const own=fs.filter(f=>f.kind!=='unavailable'&&f.sections.some(s=>s.owner==='Applicant'));return{forms:fs,own,ready:own.filter(f=>report(f).complete&&Object.keys(record(f).values).length&&!unaddressed(f).length).length,reviewed:fs.filter(f=>record(f).status==='accepted').length,waiting:fs.filter(f=>f.kind==='unavailable').length};}
  function actionable(){const fs=m.applicable(c()).filter(f=>f.kind!=='unavailable');if(staff)return fs.find(f=>record(f).status==='submitted')||fs.find(f=>record(f).status==='changes_requested')||fs.find(f=>Object.keys(record(f).values).length)||fs[0];return fs.find(f=>record(f).status==='changes_requested')||fs.find(f=>f.phase==='intake'&&(!report(f).complete||!Object.keys(record(f).values).length))||fs.find(f=>f.required&&(!report(f).complete||!Object.keys(record(f).values).length))||fs[0];}
  function render(){if(!ownList().some(x=>x.id===selected))selected=ownList()[0]?.id;$('#header-actions').innerHTML=`${staff?b('Review queue','queue'):view==='form'?b('Your application','case'):''}${inf('about','About this dashboard')}`;$('#storage-error').innerHTML=storageError?`<p class="notice warning">${esc(storageError)}</p>`:'';$('#main').innerHTML=!c()?emptyView():view==='queue'?queueView():view==='form'?formView():caseView();}
  function emptyView(){return `<h1>Your child care application</h1><p class="subline">Start with the type of service you want to open.</p>${b('Start an application','new','','primary')}`;}
  function progressView(){const fs=m.applicable(c());let ix=0;if(c().profile.contactName&&c().profile.city)ix=1;if(fs.some(f=>f.required&&f.phase==='intake')&&fs.filter(f=>f.required&&f.phase==='intake').every(f=>['submitted','accepted'].includes(record(f).status)))ix=2;if(ix===2&&fs.some(f=>f.required&&f.phase==='preopening')&&fs.filter(f=>f.required&&f.phase==='preopening').every(f=>record(f).status==='accepted'))ix=3;return `<ol class="progress" aria-label="Application steps">${['Your details','Application package','Prepare to open','Final review'].map((s,i)=>`<li class="step ${i<ix?'complete':i===ix?'active':''}" ${i===ix?'aria-current="step"':''}><span class="step-dot">${i<ix?'✓':i+1}</span><span>${s}</span></li>`).join('')}</ol>`;}
  function caseView(){const next=actionable(),s=summary();return `${staff?'<button class="back-link" data-action="queue">← All applications</button>':m.ownCases().length>1?'<button class="back-link" data-action="queue">← Your facilities</button>':''}<div class="page-heading"><div><h1>${esc(c().facilityName)}</h1><p class="subline">${esc(names[c().facilityTypeId])} · ${esc(c().city||'Community not set')} · ${esc(c().applicationNumber)} ${inf('route','About your application pathway')}</p></div>${b('Application packet','packet')}</div>${progressView()}<div class="next-action"><div class="next-copy"><p class="eyebrow">${staff?'Next review':'Your next step'}</p><h2>${next?esc(staff?`Review ${next.title.toLowerCase()}`:`Continue your ${next.title.toLowerCase()}`):'Your application is ready for the next review'}</h2></div>${next?b(staff?'Open form':'Continue', 'open-form',`data-form="${next.id}"`,'primary'):''}</div><nav class="tabs" aria-label="Application sections">${[['overview','Overview'],['profile','Provider details'],['forms','Forms & checks'],['activity','Activity']].map(([k,t])=>`<button data-action="tab" data-tab="${k}" class="${tab===k?'active':''}" ${tab===k?'aria-current="page"':''}>${t}</button>`).join('')}</nav>${tab==='profile'?profileView():tab==='forms'?formsView():tab==='activity'?activityView():overview(s)}`;}
  function formRow(f){const st=status(f),p=report(f);return `<div class="form-list-row"><div><button class="text-btn row-title" data-action="open-form" data-form="${f.id}">${esc(f.title)}</button><p class="row-subtitle">${f.kind==='unavailable'?'Provided by the Ministry':f.kind==='external'?'Issued or completed outside this dashboard':`${fields(f).filter(x=>x.owner==='Applicant'&&x.field.type!=='calculated'&&!blank(m.fieldValue(c(),f.id,x.field,x.owner))).length} answers saved${unaddressed(f).length?' · more to review':''}`}${record(f).reviewNotes.some(n=>n.status==='open')?' · Specific changes requested':''}</p></div>${badge(st.text,st.kind)}${b(staff?'Review':f.kind==='unavailable'?'View next step':'Open', 'open-form',`data-form="${f.id}"`,'small')}</div>`;}
  function overview(s){const mainForms=m.applicable(c()).filter(f=>f.phase==='intake');return `<div class="detail-grid"><section class="main-column"><div class="section-heading"><h2>${staff?'Review the application':'Complete your application package'}</h2>${inf('completion','How completion is checked')}</div><div class="forms-list">${mainForms.slice(0,5).map(formRow).join('')}</div><div class="inline-actions">${b('See every step','all-forms','','small')}${!staff?b('Review package','submit-package','data-phase="intake"','small'):''}</div><section class="latest-update"><h2>Latest update</h2>${latest()}</section></section><aside class="side-column">${staff?attentionView():`<h2>Your progress</h2><p class="team-name">${s.ready} of ${s.own.length} forms and checks prepared</p><p class="small-text muted">${s.reviewed} reviewed · ${s.waiting} Ministry-issued items</p><div class="decisions-heading"><h2>Your application team</h2><p class="team-name">Early Years · Regional consultant</p>${b('Message your coordinator','message')}</div>`}<section class="assistant-card"><div class="section-heading"><h2>${staff?'AI review':'Application helper'}</h2><span class="demo-tag">Demo</span></div><p>${staff?'Preview a focused briefing with missing answers, changes and review items.':'Get help understanding a question or preparing your next answer.'}</p>${b(staff?'Preview AI briefing':'Ask for help','ai','','small')}</section></aside></div>`;}
  function latest(){const h=c().history[c().history.length-1];return h?`<p class="small-text muted">${date(h.at||h.date)} · ${esc(h.actor)}</p><h3>${esc(h.title)}</h3><p>${esc(h.detail)}</p>`:'<p>Your draft is ready to work on.</p>';}
  function attentionView(){const items=m.getAttention(c()).filter(x=>x.kind==='submitted'||x.kind==='correction').slice(0,4);const missing=m.getAttention(c()).filter(x=>x.kind==='missing');return `<h2>Needs your attention</h2><p class="progress-caption">${missing.length} required answers · ${items.length} review items</p><div class="attention-list">${(items.length?items:missing.slice(0,3)).map(i=>`<button class="attention-item" data-action="open-form" data-form="${i.formId}" ${i.fieldId?`data-field="${esc(i.fieldId)}"`:''}><strong>${esc(m.schema(i.formId).title)}</strong><span>${esc(i.note||[i.label,i.reason].filter(Boolean).join(' — '))}</span></button>`).join('')||'<p>No flagged items.</p>'}</div>`;}
  function formsView(){const fs=m.applicable(c());return `<div class="section-heading"><h2>${staff?'Forms, checks & visits':'Your step-by-step checklist'}</h2>${inf('completion','About the checklist')}</div>${['intake','preopening','review','optional'].map(phase=>{const group=fs.filter(f=>f.phase===phase);return group.length?`<section class="doc-group"><div class="section-heading"><h3>${phaseNames[phase]}</h3>${!staff&&phase==='intake'?b('Review package','submit-package',`data-phase="${phase}"`,'small'):''}</div>${group.map(formRow).join('')}</section>`:'';}).join('')}<div class="inline-actions">${b('Other forms & grants','library','','small')}${b('Current process & sources','info','data-topic="process"','small')}</div>`;}
  function queueView(){const list=ownList().filter(x=>(!filter||x.facilityTypeId===filter)&&`${x.facilityName} ${x.city} ${x.id}`.toLowerCase().includes(query.toLowerCase()));return `<div class="page-heading"><div><h1>${staff?'Applications to review':'Your facilities'}</h1><p class="subline">${list.length} applications</p></div>${staff?b('Import case','import'):b('Add another facility','new')}</div><div class="filters"><label class="field"><span>Find an application</span><input id="queue-search" type="search" value="${esc(query)}" placeholder="Name, community or application number"></label><label class="field"><span>Service type</span><select id="queue-type"><option value="">All types</option>${Object.entries(names).map(([v,n])=>`<option value="${v}" ${filter===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="table-wrap"><table class="queue"><thead><tr><th>Application</th><th>Review status</th><th>Updated</th><th></th></tr></thead><tbody>${list.map(x=>{const fs=m.applicable(x),submitted=fs.filter(f=>m.record(x,f.id).status==='submitted').length,corrections=fs.filter(f=>m.record(x,f.id).status==='changes_requested').length;return `<tr><td><button class="text-btn case-link" data-action="case" data-id="${x.id}">${esc(x.facilityName)}</button><div class="small-text muted">${esc(names[x.facilityTypeId])} · ${esc(x.city)}<br>${esc(x.applicationNumber)}</div></td><td>${badge(submitted?`${submitted} forms to review`:corrections?`${corrections} updates requested`:'Draft in progress',submitted||corrections?'warning':'neutral')}</td><td>${date(x.updatedAt)}</td><td>${b('Open','case',`data-id="${x.id}"`,'small')}</td></tr>`}).join('')}</tbody></table></div>${list.length?'':'<p class="empty-state">No matching applications.</p>'}`;}
  function textField(label,name,value,type='text',attrs=''){return `<label class="field"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${attrs}></label>`;}
  function selectField(label,name,options,value,attrs=''){return `<label class="field"><span>${label}</span><select name="${name}" ${attrs}>${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`;}
  function profileFields(x,isNew=false){const p=x.profile||{},dis=staff&&!isNew?'disabled':'',centre=x.facilityTypeId==='centre';return `<div class="form-grid">${textField('Facility name','facilityName',x.facilityName||'','text',`required ${dis}`)}${textField('Community','city',p.city||x.city||'','text',`required ${dis}`)}${textField('First name','firstName',p.firstName||'','text',`required ${dis}`)}${textField('Last name','lastName',p.lastName||'','text',`required ${dis}`)}${textField('Email','email',p.email||'','email',`required ${dis}`)}${textField('Phone','phone',p.phone||'','tel',dis)}${textField('Street address','address',p.address||'','text',dis)}${textField('Postal code','postalCode',p.postalCode||'','text',dis)}${textField('Proposed spaces','capacity',p.capacity||'','number',`min="1" ${centre?'':`max="${x.facilityTypeId==='family_home'?8:p.applicationKind==='expand'?16:12}"`} data-provider-type="${x.facilityTypeId}" required ${dis}`)}${textField('Target opening date','openingDate',p.openingDate||'','date',dis)}${selectField('Application purpose','applicationKind',[['new','Open a new service'],['expand','Change or expand an existing licence']],p.applicationKind||'new',dis)}${selectField('Premises','premisesTenure',[['owned','Owned'],['rented','Rented']],p.premisesTenure||'owned',dis)}${centre?`${textField('Legal organization name','organizationName',p.organizationName||'','text',dis)}${selectField('Applicant structure','organizationType',[['nonprofit','Non-profit corporation'],['cooperative','Co-operative'],['municipality','Municipality'],['for_profit','For-profit corporation'],['individual','Individual'],['partnership','Partnership']],p.organizationType||'nonprofit',dis)}${selectField('Application pathway','pathway',[['centre-development','Centre development & funding consideration'],['licensing-only','Operating licence only']],p.pathway||'centre-development',dis)}`:`${textField('Adults living in the home','householdAdults',p.householdAdults??1,'number',`min="0" max="30" ${dis}`)}${selectField('Outdoor play space','outdoorPlayArea',[['on-site','At the premises'],['alternate','An alternative site is needed']],p.outdoorPlayArea||'on-site',dis)}`}<div class="field full"><details><summary>Existing licence details, if applicable</summary><div class="form-grid">${textField('Existing licence number','existingLicenceNumber',p.existingLicenceNumber||'','text',dis)}${textField('Regular licence held since','regularLicenceSince',p.regularLicenceSince||'','date',dis)}</div></details></div></div>`;}
  function profileView(){return `<section class="application-section"><div class="section-heading"><h2>Provider & facility details</h2>${inf('reuse','How your details are reused')}</div><form id="profile-form">${profileFields(c())}${staff?b('Case-specific requirements','requirements'):`<div class="form-actions"><button type="submit" class="btn primary">Save details</button></div>`}<p id="profile-error" class="error-message" role="alert"></p></form></section>`;}
  function profileData(form){const o=Object.fromEntries(new FormData(form));for(const k of ['capacity','householdAdults'])if(k in o)o[k]=o[k]===''?'':Number(o[k]);o.alternateOutdoorPlanNeeded=o.outdoorPlayArea==='alternate';o.requestingFunding=o.pathway==='centre-development'&&!['for_profit','individual','partnership'].includes(o.organizationType);o.contactName=`${o.firstName||''} ${o.lastName||''}`.trim();if(['for_profit','individual','partnership'].includes(o.organizationType)&&c()?.facilityTypeId==='centre')o.pathway='licensing-only';return o;}
  function requirements(){openModal('Case-specific requirements',`<p>Add items specifically requested by the Ministry for this case.</p>${[['ministryRequestedMedical','Medical information requested'],['ministryRequestedFinancials','Audited financial statements requested']].map(([key,label])=>`<label class="check-line"><input type="checkbox" name="${key}" ${c().profile[key]?'checked':''}> ${label}</label>`).join('')}`,v=>{m.updateProfile(c().id,{ministryRequestedMedical:!!v.ministryRequestedMedical,ministryRequestedFinancials:!!v.ministryRequestedFinancials},'Ministry');closeModal();persist('Case requirements updated');},'Save requirements');}
  function activityView(){const rows=[...c().history.filter(h=>h.title!=='Message added'),...c().messages.map(x=>({at:x.at,date:x.date,actor:x.author,title:'Message',detail:x.text}))].sort((a,b)=>String(b.at||b.date).localeCompare(String(a.at||a.date)));return `<div class="section-heading"><h2>Activity & messages</h2>${b(staff?'Add case note':'Message your coordinator','message')}</div>${rows.map(h=>`<article class="activity-item"><p class="small-text muted">${date(h.at||h.date)} · ${esc(h.actor)}</p><h3>${esc(h.title)}</h3><p>${esc(h.detail)}</p></article>`).join('')}`;}
  function loadDraft(){formDraft={};for(const x of fields(schema()))if(x.owner===actor&&x.field.type!=='calculated'&&!x.field.readonly&&!x.field.readOnly){const v=m.fieldValue(c(),formId,x.field,x.owner);if(v!==undefined)formDraft[x.field.id]=clone(v);}draftBaseline=clone(formDraft);dirty=false;}
  function openForm(id,fieldId){formId=id;const f=m.schema(id);sectionIndex=staff&&f.sections.some(s=>s.owner==='Applicant')?-1:0;if(fieldId){const index=visibleSections(f).findIndex(s=>s.fields.some(x=>x.id===fieldId));sectionIndex=staff&&index<0?-1:Math.max(0,index);}loadDraft();view='form';render();window.scrollTo({top:0});if(fieldId)setTimeout(()=>document.getElementById('field-'+fieldId)?.focus(),0);}
  function visibleSections(f){return f.sections.filter(s=>(staff?s.owner!=='Applicant':s.owner==='Applicant')&&s.fields.some(field=>m.fieldVisible(c(),f.id,field)));}
  function draftCase(){const working=clone(c());working.forms??={};working.forms[formId]??=clone(record(schema()));const rec=working.forms[formId];rec[staff?'staffValues':'values']={...rec[staff?'staffValues':'values'],...formDraft};for(const x of fields(schema()))if(x.field.bind&&Object.prototype.hasOwnProperty.call(formDraft,x.field.id)){const parts=x.field.bind.split('.');let at=working;for(const part of parts.slice(0,-1))at=at[part]??={};at[parts.at(-1)]=formDraft[x.field.id];}return working;}
  function isVisible(f,field){return m.fieldVisible(view==='form'&&f.id===formId?draftCase():c(),f.id,field);}
  function shortSection(s,i){if(s.id==='preparation')return 'Document details';return s.title.length>65?(s.id.replace(/_(applicant|ministry)$/,'').replace(/_/g,' ').replace(/^./,x=>x.toUpperCase())):s.title;}
  function allAnswersView(f){return `<section class="editor-main"><div class="section-heading"><h2>Applicant answers</h2>${b('Complete review','review-form','','primary')}</div>${f.sections.filter(s=>s.owner==='Applicant'&&s.fields.some(field=>m.fieldVisible(c(),f.id,field))).map(s=>`<section class="form-section"><h3>${esc(s.title)}</h3><div class="field-grid">${s.fields.filter(field=>isVisible(f,field)).map(field=>renderField(f,s,field)).join('')}</div></section>`).join('')}<div class="section-footer">${b('Complete review','review-form','','primary')}</div></section>`;}
  function formView(){const f=schema(),sections=visibleSections(f),s=sections[sectionIndex],rec=record(f),r=report(f);return `<div class="form-toolbar"><button class="back-link" data-action="case">← ${esc(c().facilityName)}</button><div class="inline-actions">${pendingState?b('Download unsaved answers','draft-export','','small'):''}${b(staff?'Print visit copy':'Print form','print-form','','small')}${b(staff?'AI review · Demo':'AI helper · Demo','ai','','small')}${inf('form:'+f.id,'Form source and instructions')}</div></div><div class="form-heading"><div><h1>${esc(f.title)}</h1><p class="subline">${phaseNames[f.phase]} · ${staff?'Reviewing the applicant’s actual answers':`Section ${sectionIndex+1} of ${sections.length} · saved as you continue`}</p></div>${badge(status(f).text,status(f).kind)}</div>${f.id==='centre_budget_template'?'<p class="notice">Use grant amounts confirmed by your consultant. Totals treat blank cost lines as zero; review every line before submitting.</p>':''}${f.id==='centre_development_and_operating_budgets'?`<div class="notice"><p>Prepare both budgets using the digital template, or record a budget you have prepared separately.</p>${b('Open digital budget template',staff?'open-form':'enable-form','data-form="centre_budget_template"','small')}</div>`:f.id==='home_fee_schedule'?`<div class="notice"><p>Draft your fees in the parent handbook, then confirm the separate fee schedule with your consultant.</p>${b('Open fee schedule','open-form','data-form="home_parent_handbook" data-field="fee_schedule_and_payment_policy"','small')}</div>`:''}${f.kind==='unavailable'?unavailableView(f):!sections.length&&!staff?'<p class="notice">This form is completed by an outside issuer. Print a blank copy for them; your own answers are completed in the other steps.</p>':`<div class="form-layout"><nav class="section-nav" aria-label="Form sections">${staff&&f.sections.some(s=>s.owner==='Applicant')?`<button class="section-link ${sectionIndex===-1?'active':''}" data-action="section" data-index="-1">All applicant answers</button>`:''}${sections.map((sec,i)=>`<button type="button" class="section-link ${i===sectionIndex?'active':''}" data-action="section" data-index="${i}" ${i===sectionIndex?'aria-current="step"':''}><span>${i+1}</span>${esc(shortSection(sec,i))}${sec.owner!=='Applicant'?`<small>${sec.owner==='Ministry'?'Consultant':'Outside issuer'}</small>`:''}</button>`).join('')}</nav>${staff&&sectionIndex===-1?allAnswersView(f):`<section class="editor-main"><div class="section-heading"><div><p class="eyebrow">Section ${sectionIndex+1} of ${sections.length}</p><h2>${esc(s.id==='preparation'?'Document details':s.title)}</h2></div>${inf('section','About this section')}</div>${s.owner==='External'?'<p class="notice">This part belongs to the reference, bank or other issuer. It stays blank in the applicant’s printable copy.</p>':!staff&&s.owner==='Ministry'?'<p class="notice">Your consultant completes this section during their review or visit.</p>':''}${rec.reviewNotes.filter(n=>n.status!=='resolved'&&s.fields.some(x=>x.id===n.fieldId)).map(n=>`<div class="notice warning"><strong>Requested update</strong><p>${esc(n.note)}</p></div>`).join('')}<form id="answers-form" novalidate><div class="field-grid">${s.fields.filter(field=>isVisible(f,field)).map(field=>renderField(f,s,field)).join('')}</div><p id="answers-error" class="error-message" role="alert"></p><div class="section-footer">${sectionIndex?b('Back','prev-section'):''}<span id="save-state" class="small-text muted">${dirty?'Unsaved changes':'Saved on this device'}</span>${s.owner===actor?b('Save section','save-form'):''}${sectionIndex<sections.length-1?b('Save & continue','next-section','','primary'):b(staff?'Review this form':'Review my answers','review-form','','primary')}</div></form></section>`}</div>`}`;}
  function control(field,value,attrs='',col=false){const options=(field.options||[]).map(o=>typeof o==='string'?{value:o,label:o}:o);const id=col?'':`id="field-${field.id}"`;const common=`${id} data-field="${esc(field.id)}" ${attrs}`;if(field.type==='textarea')return `<textarea ${common} rows="5">${esc(value)}</textarea>`;if(field.type==='select')return `<select ${common}><option value="">Choose an answer</option>${options.map(o=>`<option value="${esc(o.value)}" ${String(value)===String(o.value)?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`;if(field.type==='checkbox')return `<label class="check-line"><input type="checkbox" ${common} ${value?'checked':''}> ${esc(field.checkboxText||'Confirmed for this draft')}</label>`;if(field.type==='checkbox_group')return `<div class="checkbox-options">${options.map(o=>`<label class="check-line"><input type="checkbox" data-field="${esc(field.id)}" data-option="${esc(o.value)}" ${(Array.isArray(value)?value:[]).includes(o.value)?'checked':''} ${attrs}> ${esc(o.label)}</label>`).join('')}</div>`;if(field.type==='calculated')return `<p class="review-value">${esc(blank(value)?'Calculated in the official workbook; confirm current rates.':value)}</p>`;return `<input ${common} type="${['number','currency'].includes(field.type)?'number':field.type==='signature'?'text':field.type==='email'?'email':field.type==='date'?'date':'text'}" ${['number','currency'].includes(field.type)?'min="0" step="any"':''} value="${esc(value)}" maxlength="1500">`;}
  function renderField(f,s,field){const editable=s.owner===actor&&field.type!=='calculated'&&!field.readonly&&!field.readOnly;let value=editable?(formDraft[field.id]??''):m.fieldValue(view==='form'&&f.id===formId?draftCase():c(),f.id,field,s.owner);const label=field.label;const problem=report(f,actor).missing.find(x=>x.fieldId===field.id);const linked=!!field.bind;const notes=record(f).reviewNotes.filter(n=>n.fieldId===field.id&&n.status!=='resolved');return `<div class="question ${['textarea','table','checkbox_group'].includes(field.type)?'wide':''}" data-question="${esc(field.id)}"><div class="question-header"><label for="field-${field.id}">${esc(label)}${field.required?' <span aria-label="Needed for this draft">*</span>':''}</label>${linked?badge('Reused detail','success'):''}</div>${field.help&&!/^Requested field;|^Proposed local preparation|source.*not.*mark|required.*not.*marked|unmarked|completion review/i.test(field.help)?`<p class="field-help">${esc(field.help)}</p>`:''}${field.type==='table'?tableControl(field,value||[],editable):editable?control(field,value):`<div class="review-value ${blank(value)?'empty-answer':''}">${displayValue(value,field)}</div>`}${notes.map(n=>`<p class="inline-error">${esc(n.note)}</p>`).join('')}${staff&&s.owner==='Applicant'?`<div class="field-actions">${b('Request an update','correction',`data-field="${esc(field.id)}"`,'small')}${changedField(f,field)}</div>`:editable&&field.aiAllowed?`<div class="field-actions">${b('Help me draft · Demo','ai',`data-field="${esc(field.id)}"`,'small')}</div>`:''}${problem&&record(f).status==='changes_requested'?`<p class="inline-error">${esc(problem.reason)}</p>`:''}</div>`;}
  function tableControl(field,rows,editable){if(!editable)return `<div class="table-wrap"><table class="packet-table review-table"><thead><tr>${field.columns.map(col=>`<th>${esc(col.label)}</th>`).join('')}</tr></thead><tbody>${(rows.length?rows:field.fixedRows||[{}]).map(row=>`<tr>${field.columns.map(col=>`<td>${displayValue(row[col.id],col)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;const list=rows.length?rows:field.fixedRows||[],variable=!field.fixedRows&&field.allowAddRows!==false;return `<div class="repeat-rows" data-table="${esc(field.id)}">${list.map((row,i)=>`<div class="repeat-item"><div class="section-heading"><strong>${esc(row.row_label||field.rowLabel||'Entry')}${row.row_label?'':' '+(i+1)}</strong>${editable&&variable?b('Remove','remove-row',`data-field="${esc(field.id)}" data-index="${i}"`,'small'):''}</div><div class="row-grid">${field.columns.filter(col=>col.id!=='row_label').map(col=>`<label class="field"><span>${esc(col.label)}</span>${editable&&!col.readonly&&!col.readOnly&&col.type!=='calculated'?control(col,row[col.id]??'',`data-table="${esc(field.id)}" data-row="${i}"`,true):`<div class="review-value">${displayValue(row[col.id],col)}</div>`}</label>`).join('')}</div></div>`).join('')||'<p class="empty-answer">No entries yet.</p>'}${editable&&variable?b(field.addLabel||'Add entry','add-row',`data-field="${esc(field.id)}"`,'small'):''}</div>`;}
  function displayValue(v,field){if(field.type==='calculated'&&blank(v))return '<span class="empty-answer">Awaiting inputs or Ministry confirmation</span>';if(field.type==='calculated'&&typeof v==='number')return new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(v);if(blank(v))return '<span class="empty-answer">Not answered</span>';if(field.type==='checkbox')return v?'Confirmed':'Not confirmed';if(Array.isArray(v))return esc(v.map(x=>typeof x==='object'?Object.values(x).join(' · '):x).join('; '));return esc(v).replace(/\n/g,'<br>');}
  function changedField(f,field){const latest=[...record(f).revisions].reverse().find(r=>r.action==='submitted');const change=latest?.changes.find(x=>x.fieldId===field.id);return change&&!blank(change.before)?`<details class="review-diff"><summary>Changed since previous submission</summary><p><strong>Previous:</strong> ${displayValue(change.before,field)}</p><p><strong>Current:</strong> ${displayValue(change.after,field)}</p></details>`:'';}
  function unavailableView(f){return `<section class="notice"><h2>Get the current Ministry template</h2><p>${esc((Array.isArray(f.notes)?f.notes.join(' '):f.notes)||'The official opening process references this item, but a current public blank form was not available.')}</p><p>Your coordinator needs to provide or confirm this item. The dashboard will not invent its questions or mark it complete.</p><div class="inline-actions">${b('Add request to case','request-template',`data-form="${f.id}"`)}${b('View source','info',`data-topic="form:${f.id}"`)}</div></section>`;}
  function capture(){const form=$('#answers-form');if(!form||!formId)return;const s=visibleSections(schema())[sectionIndex];if(s?.owner!==actor)return;for(const field of s.fields){if(!isVisible(schema(),field)||field.type==='calculated'||field.readonly||field.readOnly)continue;let value;if(field.type==='table'){const rows=clone(formDraft[field.id]||field.fixedRows||[]);for(let i=0;i<rows.length;i++)for(const col of field.columns){if(col.readonly||col.readOnly||col.type==='calculated')continue;const els=[...form.querySelectorAll(`[data-table="${field.id}"][data-row="${i}"][data-field="${col.id}"]`)];if(!els.length)continue;rows[i][col.id]=col.type==='checkbox_group'?els.filter(el=>el.checked).map(el=>el.dataset.option):readControl(els[0],col);}value=rows;}else if(field.type==='checkbox_group'){value=[...form.querySelectorAll(`[data-field="${field.id}"][data-option]:checked`)].map(el=>el.dataset.option);}else{const el=form.querySelector(`[data-field="${field.id}"]`);if(!el)continue;value=readControl(el,field);}if(JSON.stringify(value)!==JSON.stringify(formDraft[field.id])){formDraft[field.id]=value;if(field.bind)for(const x of fields(schema()))if(x.owner===actor&&x.field.bind===field.bind)formDraft[x.field.id]=clone(value);}}}
  function readControl(el,f){if(f.type==='checkbox')return el.checked;if(['number','currency'].includes(f.type))return el.value===''?'':Number(el.value);return el.value;}
  function saveForm(draw=false){if(!dirty)return;capture();const delta={};for(const [key,value]of Object.entries(formDraft)){const before=draftBaseline[key];if(JSON.stringify(value)!==JSON.stringify(before)&&!(before===undefined&&(blank(value)||value===false)))delta[key]=value;}if(pendingState){const incoming=new FormWorkspace(seed,catalog,pendingState);for(const [key]of Object.entries(delta)){const old=draftBaseline[key],current=incoming.fieldValue(incoming.case(selected),formId,key,actor);if(JSON.stringify(old)!==JSON.stringify(current))throw Error('This answer changed in the other dashboard. Download your unsaved answers, then reload to reconcile the two versions.');}m=incoming;pendingState=null;}if(Object.keys(delta).length){m.saveForm(c().id,formId,delta,actor);loadDraft();persist('Form answers saved',draw);}else{loadDraft();if(draw)render();}if($('#save-state'))$('#save-state').textContent='Saved on this device';}
  function reviewForm(){saveForm();const f=schema(),r=report(f),rr=report(f,'Ministry'),rec=record(f),unanswered=unaddressed(f);const issues=staff?[...r.missing,...rr.missing]:r.missing;openModal(staff?'Review this form':'Check your answers',`${issues.length?`<div class="notice warning"><strong>${issues.length} required answers need attention</strong><ul>${issues.slice(0,12).map(x=>`<li>${esc(x.section)} — ${esc(x.label)}: ${esc(x.reason)}</li>`).join('')}</ul></div>`:'<p class="notice">The required answers are answered.</p>'}${unanswered.length?`<details><summary>${unanswered.length} other requested fields are blank</summary><p>Some printed fields are conditional or are not individually marked mandatory. Confirm they do not apply before submitting.</p><ul>${unanswered.map(x=>`<li>${esc(x.section.title)} — ${esc(x.field.label)}</li>`).join('')}</ul></details>`:''}<p class="small-text muted">${staff?'Accepting a form records your review. It does not issue a licence or approve a grant.':'This submits a local demonstration record for review. Nothing is sent to the Ministry.'}</p>${!staff&&unanswered.length?'<label class="check-line"><input type="checkbox" name="blankReview" required> I reviewed the unanswered fields and will confirm any applicable items with my consultant.</label>':''}${staff?'<label class="field"><span>Review note</span><textarea name="note" rows="3" required></textarea></label>':''}`,async v=>{if(staff)m.acceptForm(c().id,f.id,v.note);else m.submitForm(c().id,f.id);closeModal();view='case';tab='forms';persist(staff?'Form review recorded':'Form submitted in this demonstration');},staff?'Accept reviewed form':'Submit form for review');}
  function openModal(title,body,handler=null,submitLabel='Save',wide=false){lastFocus=document.activeElement;modalHandler=handler;const d=$('#modal');d.className='modal'+(wide?' modal-wide':'');d.innerHTML=`<form id="modal-form"><div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="icon-btn" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}<p id="modal-error" class="error-message" role="alert"></p></div><div class="modal-footer">${b(handler?'Cancel':'Close','close')}${handler?`<button type="submit" class="btn primary">${submitLabel}</button>`:''}</div></form>`;if(!d.open)d.showModal();d.querySelector('input,select,textarea,button')?.focus();}
  function closeModal(){$('#modal').close();modalHandler=null;lastFocus?.focus();}
  function sourceLinks(ids){return `<ul class="source-list">${catalog.sources.filter(s=>ids.includes(s.id)).map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>${s.version?`<p class="small-text muted">${esc(typeof s.version==='string'?s.version:JSON.stringify(s.version))}</p>`:''}</li>`).join('')}</ul>`;}
  function info(topic){let title='About this dashboard',body='';if(topic==='about')body=`<p><strong>Local demonstration with fictional cases.</strong></p><p>Applicants work on their own facility application. Ministry staff have a separate review dashboard. There is no role toggle or live government connection.</p><p>Digital forms replace retyping downloaded questionnaires. Outside-issued reports, required originals and authorized signatures still need their own verification.</p><p>AI features are labelled demonstrations. They use prepared examples and checklist results; no AI service receives your data.</p><p>Saved on this device. Individual file pages may have separate browser storage: export/import the case to transfer it between dashboards.</p><div class="inline-actions">${b('Current process & sources','info','data-topic="process"','small')}${b('Export case','export','','small')}${localStorage.getItem(KEY+'-recovery')?b('Download recovery copy','recovery','','small'):''}${b('Import case','import','','small')}${!staff?b('Start another facility','new','','small'):''}${b('Restore sample cases','reset','','small danger')}</div>`;
    else if(topic==='route'){title='Your application pathway';body=`<p><strong>${esc(names[c().facilityTypeId])}</strong></p><p>Family and group-family homes share the home licensing package. A centre uses its own needs assessment, budget and licence forms.</p><p>New group homes may initially be licensed for up to 12 spaces. Expansion beyond 12 has further conditions, including at least two years on a regular licence and Ministry approval in targeted need areas. Proposed capacity is not an approved capacity.</p><p>For-profit centre applicants do not qualify for the government centre funding programme. Confirm the direct licensing intake with the consultant.</p>${sourceLinks(catalog.sources.filter(x=>/faq|group|apply|start|centre-process/i.test(x.id+' '+x.title)).map(x=>x.id))}`;}
    else if(topic==='completion'){title='What completion means';body='<p>Complete the requested information relevant to your situation, then review and submit your draft. Asterisks identify required answers; unmarked fields can still be needed for your circumstances.</p><p>Applicant answers and consultant visit notes are separate. An applicant can submit their part before the consultant completes theirs. Original checks, outside reports and Ministry-issued templates remain visible until handled.</p><p>Form completeness is not a licensing or funding decision. Current Ministry requirements and approved forms remain authoritative.</p>';}
    else if(topic==='reuse'){title='Enter shared details once';body='<p>Your name, contact information, facility and address populate linked fields in the forms. Updating a shared detail reopens affected reviews so a reviewer can see what changed.</p>';}
    else if(topic==='section'){title=visibleSections(schema())[sectionIndex]?.title||'Form section';body=`<p>${esc(visibleSections(schema())[sectionIndex]?.help||'Answer the questions relevant to this section. Your consultant reviews their own section separately.')}</p><p>Source prompts have been organized into shorter digital sections. Use the original source to check current wording and signing requirements.</p>${sourceLinks(schema().sourceIds||[])}`;}
    else if(topic.startsWith('form:')){const f=m.schema(topic.slice(5));title=f.title;body=`<p>${esc(f.originalSubmission||'Prepare the form here; the official submission channel still applies.')}</p>${(Array.isArray(f.notes)?f.notes:[f.notes]).filter(Boolean).map(n=>`<p>${esc(n)}</p>`).join('')}<p>Applicant, consultant and outside-issuer sections retain their separate responsibilities. Printed copies are draft preparation copies, not an approved replacement for Ministry forms.</p>${f.id==='centre_budget_template'?`<h3>Budget calculations</h3><ul>${m.calculationInfo(c(),f.id).notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:''}${sourceLinks(f.sourceIds||[])}`;}
    else if(topic==='process'){title='Current process & proposed service';body=`<p>The process map lists the current steps, verified forms, responsible person and proposed improvement for each application pathway.</p><p><a href="childcare-current-process-map.html" target="_blank" rel="noopener">Open the detailed process map ↗</a></p><details><summary>Verified source library (${catalog.sources.length})</summary>${sourceLinks(catalog.sources.map(x=>x.id))}</details><p>Where a current blank template was not public, it is identified as Ministry-provided rather than recreated from assumptions.</p>`;}
    openModal(title,body,null,'Save',topic==='process');}
  function library(){const fs=m.applicable(c(),{includeOptional:true}).filter(f=>!f.required);openModal('Other forms & grants',`<p>These are conditional or optional. They do not hold up the initial application unless they apply to your selected request.</p>${fs.map(f=>`<div class="form-list-row"><div><strong>${esc(f.title)}</strong><p class="small-text muted">${esc(f.originalRequirement||phaseNames[f.phase])}</p></div>${b(staff?'View form':c().selectedOptionalFormIds.includes(f.id)?'Open':'Add to application',staff||c().selectedOptionalFormIds.includes(f.id)?'open-form':'enable-form',`data-form="${f.id}"`,'small')}</div>`).join('')}`,null,'Save',true);}
  function createApplication(){if(view==='form'&&dirty)saveForm();pendingState=null;openModal('Start an application for another facility',`<p>Choose the service you plan to operate.</p><div class="route-options">${Object.entries(names).map(([id,n],i)=>`<label class="route-option"><input name="facilityTypeId" type="radio" value="${id}" ${i===0?'checked':''}><span><strong>${n}</strong><span class="small-text">${id==='family_home'?'A residential home, within family-home capacity and age limits.':id==='group_home'?'Residential care with an assistant; initial and expansion conditions differ.':'A centre operation with its own premises, staff and governance.'}</span></span></label>`).join('')}</div>`,v=>{const type=v.facilityTypeId;openModal('Your provider details',profileFields({facilityTypeId:type,profile:{}},true),data=>{const form=$('#modal-form'),values=profileData(form);if(type==='centre'&&['for_profit','individual','partnership'].includes(values.organizationType))values.pathway='licensing-only';const x=m.create({...values,facilityTypeId:type});selected=x.id;closeModal();view='case';tab='overview';persist('New facility application started');},'Start application',true);},'Continue');}
  function correction(field){openModal('Request a specific update',`<p>${esc(fields(schema()).find(x=>x.field.id===field)?.field.label||'')}</p><label class="field"><span>What needs to change?</span><textarea name="note" rows="4" required maxlength="2000"></textarea></label><p class="small-text muted">Saved to this case; no external message is sent.</p>`,v=>{m.requestChanges(c().id,formId,{fieldId:field,note:v.note});closeModal();persist('Update request recorded');},'Request update');}
  function message(text=''){openModal(staff?'Add a case note':'Message your coordinator',`<label class="field"><span>Message</span><textarea name="message" rows="4" required maxlength="3000">${esc(text)}</textarea></label><p class="small-text muted">This demonstration saves the message to the local case only.</p>`,v=>{m.addMessage(c().id,v.message,actor);closeModal();persist('Message added to case activity');},'Save to case');}
  function ai(fieldId){if(view==='form'){capture();aiTarget=fieldId?fields(schema()).find(x=>x.field.id===fieldId):null;}else aiTarget=null;const missing=m.getAttention(c()).filter(x=>x.kind==='missing'),submitted=m.getAttention(c()).filter(x=>x.kind==='submitted'),changes=m.getAttention(c()).filter(x=>x.kind==='correction');let body=`<p><span class="demo-tag">AI demonstration</span></p>`;if(staff){body+=`<p>This preview organizes the case’s checklist results. A live assistant would explain and prioritize them; it would not make licensing, funding or suitability decisions.</p><div class="assistant-brief"><h3>Review now</h3><ul>${submitted.slice(0,4).map(x=>`<li>${esc(m.schema(x.formId).title)} — submitted answers ready to open.</li>`).join('')||'<li>No submitted forms are waiting.</li>'}</ul><h3>Missing or unresolved</h3><ul>${[...changes.slice(0,2),...missing.slice(0,4)].map(x=>`<li>${esc(m.schema(x.formId).title)}: ${esc(x.note||x.label||x.reason)}</li>`).join('')||'<li>No required-answer issues found.</li>'}</ul><p>Health, family, background and banking information is excluded from this preview. The reviewer must check the underlying form.</p></div>`;openModal('AI review briefing',body);return;}
    if(aiTarget?.field.aiAllowed){const field=aiTarget.field;body+=`<h3>${esc(aiTarget.section.title)}</h3><p>Tell the assistant the facts you want to include. In this demonstration, you can review a prepared example and choose whether to use it.</p><label class="field"><span>Your facts or notes</span><textarea id="ai-facts" rows="3">${esc(formDraft[field.id]||'')}</textarea></label><div class="inline-actions">${b('Show draft example','ai-example')}</div><div id="ai-output"></div>`;openModal('Help with this answer',body);}
    else{const f=view==='form'?schema():actionable();body+=`<h3>${esc(f?.title||'Finish your application')}</h3><p>${f?.id.includes('assessment')?'Use your own experience and household circumstances. Complete the Applicant’s Response; the visit notes belong to your consultant. Sensitive personal answers are not drafted for you.':'Work through one section at a time. Shared contact and facility details are reused. Save partial answers, then check the form for omissions before submitting.'}</p><ul><li>Explain what the question asks.</li><li>Point to unanswered required answers and the original source.</li><li>Suggest structure for a non-sensitive operational answer when you choose a drafting field.</li></ul>${f?sourceLinks(f.sourceIds||[]):''}<p class="small-text muted">This is a prepared demonstration, not a live AI response.</p>`;openModal('Application helper',body);}}
  function aiExample(){const field=aiTarget.field,topic=(aiTarget.section.title+' '+field.label).toLowerCase(),facts=$('#ai-facts').value.trim();let draft=facts?`Our plan is to ${facts.replace(/^[A-Z]/,x=>x.toLowerCase()).replace(/[.!?]$/,'')}. We will review the plan with families and our consultant before putting it into practice.`:'Describe your actual plan here, including who is responsible, the daily routine and how you will review it.';if(!facts&&/philosophy|program|learning/.test(topic))draft='Our proposed program supports learning through play, predictable routines and positive relationships. We will adapt activities to children’s ages and interests and discuss each child’s needs with their family.';if(!facts&&/supervision/.test(topic))draft='Describe who supervises each group, how attendance and transitions are checked, and how staff arrange coverage during breaks, outdoor play and emergencies.';$('#ai-output').innerHTML=`<div class="notice"><strong>Prepared draft example — verify before using</strong><textarea id="ai-draft" rows="5">${esc(draft)}</textarea><div class="inline-actions">${b('Use this draft','ai-apply','','primary')}</div></div>`;}
  function submitPackage(phase){const fs=m.applicable(c(),{phase}).filter(f=>f.required),incomplete=fs.filter(f=>!report(f).complete);openModal('Review your application package',`<p>${phaseNames[phase]}</p><ul>${fs.map(f=>`<li>${esc(f.title)} — ${report(f).complete?'configured checks answered':'needs attention'}</li>`).join('')}</ul>${incomplete.length?'<p class="notice warning">Finish the outstanding checks before submitting this package.</p>':''}<p class="small-text muted">A complete draft still needs required original documents, valid signatures and Ministry review. Nothing is sent to government from this demonstration.</p>`,()=>{m.submitPackage(c().id,phase);closeModal();persist('Package submitted in the local demonstration');},'Submit package in demo');}
  function printMarkup(f,visit=false){const packetForms=f?[f]:m.applicable(c()).filter(x=>x.required||c().selectedOptionalFormIds.includes(x.id));return `<header><p>Draft preparation copy · Saskatchewan child care application</p><h1>${esc(c().facilityName)}</h1><p>${esc(c().applicationNumber)} · ${esc(names[c().facilityTypeId])} · ${date(new Date().toISOString())}</p></header>${packetForms.map(form=>`<article class="packet-section"><h2>${esc(form.title)}</h2><p>${esc(phaseNames[form.phase])} · ${esc(status(form).text)}</p>${form.kind==='unavailable'?'<p>Current Ministry template required. No substitute form has been generated.</p>':form.sections.map(s=>`<section class="print-section"><h3>${esc(s.title)} — ${esc(s.owner==='External'?'Outside issuer':s.owner)}</h3>${s.fields.filter(field=>m.fieldVisible(c(),form.id,field)).map(field=>{let value=visit&&s.owner!=='Applicant'?undefined:m.fieldValue(c(),form.id,field,s.owner);return `<div class="print-question"><strong>${esc(field.label)}</strong>${field.signatureDraft||field.type==='signature'?`<p>Prepared name: ${esc(value||'')}<br>Signature: ____________________________________ Date: __________________</p>`:field.type==='table'?`<table class="packet-table"><thead><tr>${field.columns.map(col=>`<th>${esc(col.label)}</th>`).join('')}</tr></thead><tbody>${(Array.isArray(value)&&value.length?value:[{}]).map(row=>`<tr>${field.columns.map(col=>`<td>${blank(row[col.id])?'&nbsp;':displayValue(row[col.id],col)}</td>`).join('')}</tr>`).join('')}</tbody></table>`:`<div class="print-answer">${blank(value)?'<span>________________________________________________________________________</span><br><br>':displayValue(value,field)}</div>`}</div>`}).join('')}</section>`).join('')}${form.id==='centre_budget_template'?`<p><strong>Budget calculation notes</strong></p><ul>${m.calculationInfo(c(),form.id).notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:''}${sourceLinks(form.sourceIds||[])}</article>`).join('')}<footer>Draft only. This copy does not replace an approved Ministry template or authorized signature. Required originals and outside evidence remain separate. No licence or funding decision is made here.</footer>`;}
  const printStyle='body{font:14px/1.5 Arial,sans-serif;color:#173c2d;max-width:960px;margin:32px auto;padding:0 24px}h1{font-size:28px}h2{margin-top:36px;border-bottom:2px solid #173c2d}h3{margin-top:24px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #aaa;padding:8px;text-align:left}.print-question{margin:18px 0;break-inside:avoid}.print-answer{padding:10px 0}.source-list{font-size:11px}footer{border-top:1px solid #aaa;margin-top:30px;font-size:11px}@media print{body{margin:0;padding:0}.packet-section{break-before:page}.packet-section:first-of-type{break-before:auto}a{color:inherit}}';
  function download(name,text,mime){const url=URL.createObjectURL(new Blob([text],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function packetView(){if(view==='form'&&dirty)saveForm();const s=summary();openModal('Your application packet',`<p><strong>${esc(c().facilityName)}</strong></p><p>${s.ready} forms and checks prepared · ${s.reviewed} reviewed · ${s.waiting} Ministry-issued items remain.</p><p>The packet contains your actual answers, consultant notes, blank issuer sections, sources and outstanding items. You can print it or save a copy for review.</p><div class="inline-actions">${b('Download printable packet','download-packet','','primary')}${b('Print packet','print-packet')}${b('Export editable case','export')}</div><details><summary>What still needs to happen?</summary><ul>${m.applicable(c()).filter(f=>record(f).status!=='accepted').map(f=>`<li>${esc(f.title)} — ${esc(status(f).text)}</li>`).join('')}</ul></details>`,null,'Save',true);}
  function importCase(){if(view==='form'&&dirty)saveForm();pendingState=null;openModal('Import an editable case',`<label class="field"><span>Case export (.json)</span><input id="import-file" type="file" accept=".json,application/json" required></label><p>Only this dashboard’s form exports are accepted. Importing cannot change ownership.</p>`,async()=>{const file=$('#import-file').files[0];if(!file||file.size>3000000)throw Error('Choose a case export smaller than 3 MB.');const data=JSON.parse(await file.text());const apply=replace=>{const x=m.importCase(data,{replace});if(!staff&&x.ownerId!=='demo-applicant')throw Error('That case belongs to another applicant. Import it in the Ministry dashboard.');selected=x.id;closeModal();view='case';tab='overview';persist('Case imported');};if(!staff&&data?.case?.ownerId!=='demo-applicant')throw Error('That case belongs to another applicant.');if(m.state.cases.some(x=>x.id===data.case?.id))openModal('Replace this case?',`<p>This will replace the existing local form answers and review history for ${esc(data.case.facilityName)}. Export the current case first if you want to keep it.</p>`,()=>apply(true),'Replace case');else apply(false);},'Import');}
  document.addEventListener('click',async e=>{const t=e.target.closest('[data-action]');if(!t)return;const a=t.dataset.action;try{if(a==='close')closeModal();else if(a==='case'){if(view==='form'&&dirty)saveForm();if(t.dataset.id)selected=t.dataset.id;view='case';formId=null;tab='overview';render();window.scrollTo({top:0});}else if(a==='queue'){if(view==='form'&&dirty)saveForm();view='queue';render();}else if(a==='tab'){tab=t.dataset.tab;render();}else if(a==='all-forms'){tab='forms';render();}else if(a==='open-form'){if($('#modal').open)closeModal();if(view==='form'&&dirty)saveForm();openForm(t.dataset.form,t.dataset.field);}else if(a==='section'||a==='next-section'||a==='prev-section'){saveForm();sectionIndex=a==='section'?Number(t.dataset.index):sectionIndex+(a==='next-section'?1:-1);render();window.scrollTo({top:0});}else if(a==='save-form')saveForm(true);else if(a==='review-form')reviewForm();else if(a==='add-row'){capture();const f=fields(schema()).find(x=>x.field.id===t.dataset.field).field;formDraft[f.id]??=[];formDraft[f.id].push(Object.fromEntries(f.columns.map(col=>[col.id,col.type==='checkbox'?false:''])));dirty=true;render();}else if(a==='remove-row'){capture();formDraft[t.dataset.field].splice(Number(t.dataset.index),1);dirty=true;render();}else if(a==='correction')correction(t.dataset.field);else if(a==='draft-export'){capture();download(`${c().applicationNumber}-unsaved-answers.json`,JSON.stringify({applicationNumber:c().applicationNumber,formId,actor,unsavedAnswers:formDraft},null,2),'application/json');}else if(a==='requirements')requirements();else if(a==='recovery'){download('previous-case-recovery.json',localStorage.getItem(KEY+'-recovery')||'null','application/json');}else if(a==='info')info(t.dataset.topic);else if(a==='library')library();else if(a==='enable-form'){m.enableForm(c().id,t.dataset.form,true);persist('Form added',false);closeModal();openForm(t.dataset.form);}else if(a==='new')createApplication();else if(a==='message')message();else if(a==='request-template')message(`Please provide the current ${m.schema(t.dataset.form).title} and confirm the steps that apply to my application.`);else if(a==='ai')ai(t.dataset.field);else if(a==='ai-example')aiExample();else if(a==='ai-apply'){formDraft[aiTarget.field.id]=$('#ai-draft').value;dirty=true;closeModal();render();toast('Draft added. Review it before saving.');}else if(a==='submit-package')submitPackage(t.dataset.phase);else if(a==='packet')packetView();else if(a==='download-packet'){download(`${c().applicationNumber}-draft-packet.html`,`<!doctype html><html lang="en"><meta charset="utf-8"><title>Draft application packet</title><style>${printStyle}</style><body>${printMarkup()}</body></html>`,'text/html');toast('Printable packet downloaded');}else if(a==='print-form'||a==='print-packet'){if(view==='form'&&dirty)saveForm();const visit=a==='print-form'&&staff;$('#print-root').innerHTML=printMarkup(a==='print-form'?schema():null,visit);openModal(visit?'Print or save a visit copy':'Print or save a prepared copy',`<p>${visit?'The copy includes applicant answers and blank spaces for your visit notes.':'The copy includes the saved answers and outstanding items.'}</p><div class="inline-actions">${b('Download printable copy','download-printcopy','','primary')}${b('Print','print-prepared')}</div><p class="small-text muted">You can also open the downloaded copy in your browser and print it there.</p>`);}else if(a==='download-printcopy'){download(`${c().applicationNumber}-prepared-copy.html`,`<!doctype html><html lang="en"><meta charset="utf-8"><title>Prepared application copy</title><style>${printStyle}</style><body>${$('#print-root').innerHTML}</body></html>`,'text/html');toast('Printable copy downloaded');}else if(a==='print-prepared'){closeModal();window.print();}else if(a==='export'){if(view==='form'&&dirty)saveForm();download(`${c().applicationNumber}-forms.json`,JSON.stringify(m.exportCase(c().id),null,2),'application/json');toast('Editable case exported');}else if(a==='import')importCase();else if(a==='reset')openModal('Restore the sample cases?',`<p>This replaces local forms with the original fictional examples. Export any work you want to keep first.</p>`,()=>{m=new FormWorkspace(seed,catalog);selected=(staff?m.state.cases:m.ownCases())[0].id;view='case';tab='overview';closeModal();persist('Sample cases restored');},'Restore samples');}catch(err){toast(err.message);if($('#answers-error'))$('#answers-error').textContent=err.message;}});
  document.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='modal-form'&&modalHandler){const handler=modalHandler;await handler(Object.fromEntries(new FormData(e.target)));}else if(e.target.id==='profile-form'){m.updateProfile(c().id,profileData(e.target));persist('Shared details saved');}}catch(err){const target=e.target.id==='modal-form'?$('#modal-error'):$('#profile-error');if(target)target.textContent=err instanceof SyntaxError?'This is not a valid case export.':err.message;}});
  document.addEventListener('input',e=>{if(e.target.closest('#answers-form')){dirty=true;if($('#save-state'))$('#save-state').textContent='Unsaved changes';}if(e.target.id==='queue-search'){query=e.target.value;const pos=e.target.selectionStart;render();$('#queue-search').focus();$('#queue-search').setSelectionRange(pos,pos);}});
  document.addEventListener('change',e=>{if(e.target.id==='queue-type'){filter=e.target.value;render();}if(e.target.closest('#answers-form')){capture();dirty=true;if(e.target.tagName==='SELECT'||e.target.type==='checkbox')render();}if(e.target.name==='applicationKind'){const cap=e.target.form?.querySelector('[name="capacity"]');if(cap?.dataset.providerType==='group_home')cap.max=e.target.value==='expand'?'16':'12';}if(e.target.name==='organizationType'){const path=e.target.form?.querySelector('[name="pathway"]');if(path&&['for_profit','individual','partnership'].includes(e.target.value))path.value='licensing-only';}});
  window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const incoming=JSON.parse(e.newValue);if(dirty){capture();pendingState=incoming;render();toast('An update arrived. Your changed answers will be merged when you save.');return;}m=new FormWorkspace(seed,catalog,incoming);if(view==='form')loadDraft();render();toast('Case updated in the other dashboard');}catch{toast('An incoming case update could not be loaded.');}}});
  window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
  render();
})();
